    async function save(apply){if(saveBusy)return false;if(frozen||ctx.isClosed&&ctx.isClosed()){el.querySelector('[data-status]').textContent='Compra finalizada: valores congelados.';return;}if(!root.permisoModulo || !root.permisoModulo('balancecompra'))return;if(quoteBusy){el.querySelector('[data-status]').textContent='Esperá a que termine la consulta USDT.';return;}if(apply&&missing.length){pendingVisible=true;updatePending();el.querySelector('[data-status]').textContent='Revisá los campos indicados debajo.';pendingBox.scrollIntoView({block:'center'});pendingBox.focus({preventScroll:true});return;}saveBusy=true;const buttons=el.querySelectorAll('[data-save],[data-apply],[data-choice]');buttons.forEach(b=>b.disabled=true);try{const snapshot=JSON.parse(JSON.stringify({version:4,importHistory:importHistory,...(pendingPDF?{pdfImport:pendingPDF}:{}),extras:extras,complete:missing.length===0,pending:missing.slice(),parameters:p,rows:rows,previewChoice:el.querySelector('[data-choice]').value,choiceMode:manualChoice?'manual':'auto',chosen:el.querySelector('[data-choice]').value,result,updatedAt:Date.now(),updatedBy:root.currentUser||''}));await ctx.save(snapshot);const changedDuringSave=JSON.stringify({parameters:p,rows,extras})!==JSON.stringify({parameters:snapshot.parameters,rows:snapshot.rows,extras:snapshot.extras});delete snapshot.pdfImport;pendingPDF=null;dirty=changedDuringSave;saved=JSON.parse(JSON.stringify(snapshot));render();el.querySelector('[data-status]').textContent=dirty?'Hay cambios posteriores pendientes de guardar':apply?'Escenario guardado en la planificación':'Simulación guardada';return true;}catch(e){el.querySelector('[data-status]').textContent='No se pudo guardar: '+e.message;}finally{saveBusy=false;buttons.forEach(b=>b.disabled=false);}}
